import numpy as np
from scipy.optimize import least_squares
t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
sq=np.sqrt(P)
vy=np.var(y)
def model(p,kind):
    base=p[0]*sq+p[1]*P*np.sin(p[2]*t+p[3])
    if kind==0: extra=p[4]*P**p[7]*np.sin(p[5]*t+p[6])
    else: extra=p[4]*P**p[7]*np.exp(-p[8]*t)*np.sin(p[5]*t+p[6])
    return base+extra
rng=np.random.default_rng(1)
for kind in [0,1]:
    best=(1e9,None)
    for k in range(60):
        x0=np.array([4,1,0.42,3.1,rng.normal(),rng.uniform(0,2),rng.uniform(0,6),rng.uniform(0.2,2),rng.uniform(0,0.5)])
        try:
            s=least_squares(lambda p: model(p,kind)-y,x0)
            v=np.mean(s.fun**2)/vy
            if v<best[0]: best=(v,s.x)
        except Exception as e: pass
    print(kind,best[0],np.round(best[1],4),flush=True)

